import React, { Component } from "react";
import "./Contactus.css";
import FormJson from './formid';
import PagesJson from './PagesJson';


export default class Contactus extends Component {
    constructor(props) {
        super(props);
        this.state = {
        contactuspage: null,
        };
    }

    componentDidMount() {
        const pageName = "Contactus";
        fetch(`http://localhost:3001/${pageName}`) 
            .then(response => response.json())
            .then(page => {
                this.setState({ contactuspage: page });
            })
            .catch(error => console.error('Error fetching data:', error));
    }

    render() {
        const { contactuspage } = this.state;
        if (!contactuspage) return <div>PAGE NOT FOUND</div>;
        const contentContact = contactuspage.content;

        const page1=PagesJson.find(item => item.PageName === "ContactUs");


        return(

            <div className="contact-containerr">
                <div className="rectangle">
                    <h1><a href="#" className="contact1">{page1.PageName}</a></h1>
                    <p className="foryou">{page1.content}</p>

                    {contentContact.map((item) =>(
                       <>
                    <input type={item.type} className={item.className} placeholder={item.placeholder} required />
                    </>
                     ))}
                < input type="submit" className="sendbutton" value="Send"/>
           </div>
            </div>
      );
    }     
}
